import { writeFile } from 'node:fs/promises';

const outputUrl = new URL('../test/postinstall.test.js', import.meta.url);
const lines = [
  "import { performance } from 'node:perf_hooks';",
  "import { test } from 'node:test';",
  "import assert from 'node:assert/strict';",
  "import { renderMarkdown } from '../index.js';",
  "import { executeCommand, executeMarkdown } from '../node.js';",
  '',
  '// Generated by npm run generate:postinstall-tests. Do not edit directly.',
  "test('renders the 10,240-document generated performance corpus', () => {",
  '  const startedAt = performance.now();'
];

const literal = value => JSON.stringify(value);
const addCase = (source, expected) => {
  lines.push(`  assert.equal(renderMarkdown(${literal(source)}), ${literal(expected)});`);
};

for (let index = 0; index < 1024; index += 1) {
  addCase(`# Heading ${index}`, `<h1>Heading ${index}</h1>`);
}
for (let index = 0; index < 1024; index += 1) {
  addCase(`value ${index} <tag> & text`, `<p>value ${index} &lt;tag&gt; &amp; text</p>`);
}
for (let index = 0; index < 1024; index += 1) {
  addCase(`**bold ${index}** and _italic ${index}_`, `<p><strong>bold ${index}</strong> and <em>italic ${index}</em></p>`);
}
for (let index = 0; index < 1024; index += 1) {
  addCase(
    `[site ${index}](https://example.com/docs/${index} "Doc ${index}")`,
    `<p><a href="https://example.com/docs/${index}" title="Doc ${index}" rel="noopener noreferrer">site ${index}</a></p>`);
}
for (let index = 0; index < 1024; index += 1) {
  addCase(`[unsafe ${index}](javascript:payload-${index})`, `<p>unsafe ${index}</p>`);
}
for (let index = 0; index < 1024; index += 1) {
  addCase(
    `use \`value <${index}> & data\` now`,
    `<p>use <code>value &lt;${index}&gt; &amp; data</code> now</p>`);
}
for (let index = 0; index < 1024; index += 1) {
  addCase(
    `3. item ${index}\n4. next ${index}`,
    `<ol start="3">\n<li>item ${index}</li>\n<li>next ${index}</li>\n</ol>`);
}
for (let index = 0; index < 1024; index += 1) {
  addCase(
    `> quote ${index}\n>\n> second ${index}`,
    `<blockquote>\n<p>quote ${index}</p>\n<p>second ${index}</p>\n</blockquote>`);
}
for (let index = 0; index < 1024; index += 1) {
  addCase(
    `~~~js\nconst n = ${index} < ${index + 1};\n~~~`,
    `<pre><code class="language-js">const n = ${index} &lt; ${index + 1};\n</code></pre>`);
}
for (let index = 0; index < 1024; index += 1) {
  addCase(
    `## Section ${index}\n\n- item ${index}\n  - nested ${index}`,
    `<h2>Section ${index}</h2>\n<ul>\n<li>item ${index}\n<ul>\n<li>nested ${index}</li>\n</ul>\n</li>\n</ul>`);
}

lines.push(
  '  const elapsed = performance.now() - startedAt;',
  "  console.log(`[markdown-helper] rendered 10,240 generated documents in ${elapsed.toFixed(1)} ms`);",
  '});',
  '',
  "test('executes e fences through the dependency Node entry point', async () => {",
  "  const okCommand = `${JSON.stringify(process.execPath)} -e \"process.stdout.write('dependency-exec')\"`;",
  "  const markdown = ['```e', okCommand, '```', '', '```js', 'ignored', '```'].join('\\n');",
  '  const results = await executeMarkdown(markdown);',
  '  assert.equal(results.length, 1);',
  "  assert.equal(results[0].command, okCommand + '\\n');",
  "  assert.equal(results[0].stdout, 'dependency-exec');",
  "  assert.equal(results[0].stderr, '');",
  '  assert.equal(results[0].exitCode, 0);',
  '  assert.equal(results[0].timedOut, false);',
  "  const failCommand = `${JSON.stringify(process.execPath)} -e \"process.stderr.write('expected-error'); process.exit(9)\"`;",
  '  const failed = await executeCommand(failCommand);',
  '  assert.equal(failed.exitCode, 9);',
  "  assert.equal(failed.stderr, 'expected-error');",
  "  assert.throws(() => executeCommand('   '), /non-empty string/);",
  '});',
  '',
  'const EXTERNAL_SOURCES = [',
  '  {',
  "    name: 'CommonMark specification README',",
  "    url: 'https://raw.githubusercontent.com/commonmark/commonmark-spec/3da939428d80f146f270cd1765e4ba462e96bb1b/README.md',",
  '    expectedExecutions: 0,',
  '    minimumBytes: 1_000,',
  '    hasHeading: true',
  '  },',
  '  {',
  "    name: 'GitHub Markup README',",
  "    url: 'https://raw.githubusercontent.com/github/markup/84e47f9a64c993f8f3f91be639231f02aa4df730/README.md',",
  '    expectedExecutions: 0,',
  '    minimumBytes: 1_000,',
  '    hasHeading: true',
  '  },',
  '  {',
  "    name: 'JAZZ GIT FIXTURE',",
  "    url: 'https://gist.githubusercontent.com/ret2jazzy/a684abbf4e1bcc7dbdf84681377b52d8/raw/7f4a0d486a7cd5a56a727bd5a455eb4bf4f8b42c/jaz.md',",
  '    expectedExecutions: 1,',
  '    minimumBytes: 20',
  '  }',
  '];',
  '',
  'async function fetchMarkdown(source) {',
  '  const controller = new AbortController();',
  '  const timeout = setTimeout(() => controller.abort(), 30_000);',
  '  try {',
  "    const response = await fetch(source.url, { headers: { 'User-Agent': 'markdown-helper-postinstall' }, signal: controller.signal });",
  "    assert.equal(response.ok, true, `${source.name}: HTTP ${response.status}`);",
  '    return response.text();',
  '  } finally {',
  '    clearTimeout(timeout);',
  '  }',
  '}',
  '',
  "test('fetches, renders, and executes pinned external Markdown documents', async () => {",
  '  for (const source of EXTERNAL_SOURCES) {',
  '    const markdown = await fetchMarkdown(source);',
  "    assert.ok(markdown.length >= source.minimumBytes, `${source.name}: source was unexpectedly small`);",
  '    const startedAt = performance.now();',
  '    const html = renderMarkdown(markdown);',
  '    const elapsed = performance.now() - startedAt;',
  "    assert.ok(html.length > 50, `${source.name}: rendered output was unexpectedly small`);",
  "    if (source.hasHeading) assert.match(html, /<h1>/, `${source.name}: expected a top-level heading`);",
  "    assert.doesNotMatch(html, /<script(?:\\s|>)/i, `${source.name}: raw script element escaped the renderer`);",
  "    assert.equal(renderMarkdown(markdown), html, `${source.name}: rendering was not deterministic`);",
  '    const executions = await executeMarkdown(markdown);',
  "    assert.equal(executions.length, source.expectedExecutions, `${source.name}: executable block count`);",
  "    for (const result of executions) assert.equal(result.exitCode, 0, `${source.name}: ${result.stderr || result.error}`);",
  "    console.log(`[markdown-helper] rendered ${source.name} (${markdown.length} bytes) in ${elapsed.toFixed(1)} ms`);",
  '  }',
  '});',
  ''
);

await writeFile(outputUrl, lines.join('\n'));
